using System.Buffers.Binary;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging.Abstractions;
using Shop.Modules.Catalog.Media;
using Shop.SharedKernel;
using SkiaSharp;
using Xunit;
namespace Shop.Tests;

public sealed class PublicImageTests
{
    public static byte[] Image(SKEncodedImageFormat format=SKEncodedImageFormat.Png,int width=128,int height=96){using var bitmap=new SKBitmap(width,height);using(var canvas=new SKCanvas(bitmap)){canvas.Clear(SKColors.White);using var paint=new SKPaint();paint.Color=SKColors.Red;canvas.DrawRect(0,0,width/2f,height/2f,paint);paint.Color=SKColors.Lime;canvas.DrawRect(width/2f,0,width/2f,height/2f,paint);paint.Color=SKColors.Blue;canvas.DrawRect(0,height/2f,width/2f,height/2f,paint);paint.Color=SKColors.Yellow;canvas.DrawRect(width/2f,height/2f,width/2f,height/2f,paint);}using var image=SKImage.FromBitmap(bitmap);using var data=image.Encode(format,100);return data.ToArray();}
    [Theory][InlineData(SKEncodedImageFormat.Png,"image.png","image/png")][InlineData(SKEncodedImageFormat.Jpeg,"image.jpg","image/jpeg")][InlineData(SKEncodedImageFormat.Webp,"image.webp","image/webp")]
    public void ReencodesPixelsIntoThreeBoundedWebpImages(SKEncodedImageFormat format,string filename,string type){var source=Image(format,width:2400,height:1800);var result=new SkiaImageSanitizer().Sanitize(source,filename,type,default);Assert.Equal([320,960,1920],result.Variants.Select(v=>v.Width));foreach(var v in result.Variants){Assert.Equal(v.Width*3/4,v.Height);Assert.Equal(Convert.ToHexStringLower(SHA256.HashData(v.Bytes)),v.Sha256);using var data=SKData.CreateCopy(v.Bytes);using var codec=SKCodec.Create(data);Assert.Equal(SKEncodedImageFormat.Webp,codec.EncodedFormat);Assert.Equal(SKEncodedOrigin.TopLeft,codec.EncodedOrigin);}}
    [Theory][InlineData(1,0)][InlineData(2,1)][InlineData(3,3)][InlineData(4,2)][InlineData(5,0)][InlineData(6,2)][InlineData(7,3)][InlineData(8,1)]
    public void AppliesAllExifOrientationsAndDropsOriginalMetadata(int orientation,int corner){var marker=Encoding.ASCII.GetBytes("PRIVATE-GPS-MARKER");var source=Exif(Image(SKEncodedImageFormat.Jpeg),(ushort)orientation,marker);var result=new SkiaImageSanitizer().Sanitize(source,"photo.jpeg","image/jpeg",default);Assert.Equal(orientation>=5?96:128,result.Width);Assert.Equal(orientation>=5?128:96,result.Height);var encoded=result.Variants.Single(v=>v.Name=="card").Bytes;Assert.True(encoded.AsSpan().IndexOf(marker)<0);using var bitmap=SKBitmap.Decode(encoded);var color=bitmap.GetPixel(bitmap.Width/4,bitmap.Height/4);SKColor[] expected=[SKColors.Red,SKColors.Lime,SKColors.Blue,SKColors.Yellow];var wanted=expected[corner];Assert.InRange(Math.Abs(color.Red-wanted.Red),0,25);Assert.InRange(Math.Abs(color.Green-wanted.Green),0,25);Assert.InRange(Math.Abs(color.Blue-wanted.Blue),0,25);}
    [Fact] public void RejectsSpoofedSvgWrongMimeOversizedDimensionsAndTruncatedPixels(){var sanitizer=new SkiaImageSanitizer();var png=Image();foreach(var (bytes,name,type) in new[]{(png,"photo.svg","image/png"),(png,"photo.png","image/jpeg"),(Encoding.UTF8.GetBytes("<svg onload='x()'></svg>"),"photo.png","image/png"),(png[..40],"photo.png","image/png")})Assert.Throws<BusinessException>(()=>sanitizer.Sanitize(bytes,name,type,default));var tooWide=Image(width:9000,height:32);Assert.Equal("image_dimensions",Assert.Throws<BusinessException>(()=>sanitizer.Sanitize(tooWide,"wide.png","image/png",default)).Code);Assert.Equal("image_too_large",Assert.Throws<BusinessException>(()=>ImageEnvelope.Validate(new byte[ImageLimits.MaxInputBytes+1],"large.png","image/png")).Code);}
    [Theory][InlineData("\n")][InlineData("\r")][InlineData("\r\n")][InlineData("?download=1")][InlineData("/../raw.webp")][InlineData("%0a")]
    public void IssuedImageIdentifiersAndUrlsRejectEverySuffix(string suffix){var id=new string('a',32);var path=PublicImagePaths.Url(id,"card");Assert.True(PublicImagePaths.TryParse(path,out var parsed,out var variant));Assert.Equal(id,parsed);Assert.Equal("card",variant);Assert.False(PublicImagePaths.TryParse(path+suffix,out _,out _));Assert.Throws<BusinessException>(()=>PublicImagePaths.Key(id+suffix,"card"));}
    [Fact] public async Task MalwareAndUnconfiguredDependenciesCannotPublishAnything(){var repo=new MemoryImages();var store=new MemoryStore();var scan=new Scanner{Reject=true};var service=Service(repo,store,scan);await Assert.ThrowsAsync<BusinessException>(()=>service.UploadAsync(Image(),"p.png","image/png","actor",default));Assert.Empty(repo.Assets);Assert.Empty(store.Objects);scan.Reject=false;scan.Configured=false;Assert.Equal("media_unavailable",(await Assert.ThrowsAsync<BusinessException>(()=>service.UploadAsync(Image(),"p.png","image/png","actor",default))).Code);Assert.Empty(repo.Assets);}
    [Fact] public async Task FailedPartialWriteIsNeverReadableAndOwnObjectsAreRemoved(){var repo=new MemoryImages();var store=new MemoryStore{FailWrite=2};var service=Service(repo,store,new Scanner());await Assert.ThrowsAsync<IOException>(()=>service.UploadAsync(Image(),"p.png","image/png","actor",default));Assert.Empty(store.Objects);var asset=Assert.Single(repo.Assets).Value;Assert.Equal("Failed",asset.Status);Assert.Null(await service.ReadAsync(asset.Id,"card",default));}
    [Fact] public async Task CancelledPartialUploadCleansItsOwnObjectsWithAnIndependentDeadline(){var repo=new MemoryImages();using var request=new CancellationTokenSource();var store=new CancelAfterWriteStore(request);var service=new PublicImageService(repo,store,new Scanner(),new SkiaImageSanitizer(),NullLogger<PublicImageService>.Instance);await Assert.ThrowsAsync<OperationCanceledException>(()=>service.UploadAsync(Image(),"p.png","image/png","actor",request.Token));Assert.True(request.IsCancellationRequested);Assert.Equal(3,store.CleanupCalls);Assert.Empty(store.Inner.Objects);Assert.Equal("Failed",Assert.Single(repo.Assets).Value.Status);}
    [Fact] public async Task UncertainReadyAcknowledgementPreservesCommittedImmutableObjects(){var repo=new MemoryImages{LoseReadyAcknowledgement=true};var store=new MemoryStore();var service=Service(repo,store,new Scanner());await Assert.ThrowsAsync<IOException>(()=>service.UploadAsync(Image(),"p.png","image/png","actor",default));var asset=Assert.Single(repo.Assets).Value;Assert.Equal("Ready",asset.Status);Assert.Equal(3,store.Objects.Count);Assert.NotNull(await service.ReadAsync(asset.Id,"card",default));}
    [Fact] public async Task PublicReadsRequireReadyMetadataAndRejectTamperedStorage(){var repo=new MemoryImages();var store=new MemoryStore();var service=Service(repo,store,new Scanner());var dto=await service.UploadAsync(Image(),"p.png","image/png","actor",default);Assert.Equal(PublicImagePaths.Url(dto.Id,"card"),dto.Url);Assert.NotNull(await service.ReadAsync(dto.Id,"card",default));store.Objects[PublicImagePaths.Key(dto.Id,"card")][0]^=1;Assert.Equal("media_unavailable",(await Assert.ThrowsAsync<BusinessException>(()=>service.ReadAsync(dto.Id,"card",default))).Code);Assert.False(PublicImagePaths.TryParse("/media/catalog/../raw.webp",out _,out _));Assert.Throws<BusinessException>(()=>PublicImagePaths.Key("../other","card"));}
    [Fact] public async Task DevelopmentStoreCannotRunInProductionOrReadOutsideIssuedKeys(){Assert.Throws<InvalidOperationException>(()=>new DevelopmentImageStore("unused",false));var folder=Path.Combine(Path.GetTempPath(),"sayman-image-"+Guid.NewGuid().ToString("N"));try{var store=new DevelopmentImageStore(folder,true);var variant=new SkiaImageSanitizer().Sanitize(Image(),"p.png","image/png",default).Variants[0];var id=Guid.NewGuid().ToString("N");await store.PutAsync(id,variant,default);Assert.Equal(variant.Bytes,await store.ReadAsync(id,variant.Name,variant.Bytes.Length,default));await Assert.ThrowsAsync<IOException>(()=>store.PutAsync(id,variant,default));Assert.Throws<BusinessException>(()=>PublicImagePaths.Validate(id,"../../private"));await store.DeleteAsync(id,variant.Name,default);Assert.Null(await store.ReadAsync(id,variant.Name,variant.Bytes.Length,default));}finally{Directory.Delete(folder,true);}}
    [Theory][InlineData("stream: OK",true)][InlineData("stream: Eicar-Test-Signature FOUND",false)][InlineData("INSTREAM size limit exceeded. ERROR",false)]
    public async Task ClamAvProtocolUsesFramedBytesAndFailsClosed(string reply,bool clean){using var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();var input=Image();var server=Task.Run(async()=>{using var connection=await listener.AcceptTcpClientAsync();await using var stream=connection.GetStream();var command=new byte[10];await stream.ReadExactlyAsync(command);Assert.Equal("zINSTREAM\0",Encoding.ASCII.GetString(command));using var bytes=new MemoryStream();var size=new byte[4];while(true){await stream.ReadExactlyAsync(size);var length=BinaryPrimitives.ReadInt32BigEndian(size);if(length==0)break;var chunk=new byte[length];await stream.ReadExactlyAsync(chunk);bytes.Write(chunk);}Assert.Equal(input,bytes.ToArray());await stream.WriteAsync(Encoding.ASCII.GetBytes(reply+'\0'));});var scanner=new ClamAvScanner(new("127.0.0.1",((IPEndPoint)listener.LocalEndpoint).Port));if(clean)await scanner.ScanAsync(input,default);else await Assert.ThrowsAsync<BusinessException>(()=>scanner.ScanAsync(input,default));await server;}
    private static byte[] Exif(byte[] jpeg,ushort orientation,byte[] comment){byte[] tiff=[0x49,0x49,42,0,8,0,0,0,1,0,0x12,1,3,0,1,0,0,0,(byte)orientation,0,0,0,0,0,0,0];using var output=new MemoryStream();output.Write(jpeg,0,2);output.Write(new byte[]{255,225,0,34});output.Write("Exif\0\0"u8);output.Write(tiff);output.Write(new byte[]{255,254,0,(byte)(comment.Length+2)});output.Write(comment);output.Write(jpeg,2,jpeg.Length-2);return output.ToArray();}
    private static PublicImageService Service(MemoryImages repo,MemoryStore store,Scanner scanner)=>new(repo,store,scanner,new SkiaImageSanitizer(),NullLogger<PublicImageService>.Instance);
    private sealed class CancelAfterWriteStore(CancellationTokenSource request):IPublicImageStore{public MemoryStore Inner{get;}=new();public int CleanupCalls;public bool Configured=>true;public async Task PutAsync(string id,SanitizedVariant variant,CancellationToken ct){await Inner.PutAsync(id,variant,ct);request.Cancel();ct.ThrowIfCancellationRequested();}public Task<byte[]?> ReadAsync(string id,string name,int expected,CancellationToken ct)=>Inner.ReadAsync(id,name,expected,ct);public Task DeleteAsync(string id,string name,CancellationToken ct){ct.ThrowIfCancellationRequested();CleanupCalls++;return Inner.DeleteAsync(id,name,ct);}}
    public sealed class Scanner:IImageScanner{public bool Configured{get;set;}=true;public bool Reject{get;set;}public Task ScanAsync(ReadOnlyMemory<byte> bytes,CancellationToken ct){if(Reject)throw new BusinessException("image_rejected","test");return Task.CompletedTask;}}
    public sealed class MemoryStore:IPublicImageStore{public Dictionary<string,byte[]> Objects{get;}=[];public int FailWrite{get;set;}private int writes;public bool Configured=>true;public Task PutAsync(string id,SanitizedVariant v,CancellationToken ct){Objects.Add(PublicImagePaths.Key(id,v.Name),v.Bytes.ToArray());if(++writes==FailWrite)throw new IOException("test partial write");return Task.CompletedTask;}public Task<byte[]?> ReadAsync(string id,string name,int bytes,CancellationToken ct)=>Task.FromResult(Objects.GetValueOrDefault(PublicImagePaths.Key(id,name)));public Task DeleteAsync(string id,string name,CancellationToken ct){Objects.Remove(PublicImagePaths.Key(id,name));return Task.CompletedTask;}}
    public sealed class MemoryImages:IPublicImageRepository{public Dictionary<string,PublicImageAsset> Assets{get;}=[];public bool LoseReadyAcknowledgement{get;set;}public Task StageAsync(PublicImageAsset asset,CancellationToken ct){Assets.Add(asset.Id,asset);return Task.CompletedTask;}public Task ReadyAsync(PublicImageAsset asset,SanitizedImage image,CancellationToken ct){asset.Variants=image.Variants.Select(v=>new PublicImageVariant{AssetId=asset.Id,Name=v.Name,Width=v.Width,Height=v.Height,Bytes=v.Bytes.Length,Sha256=v.Sha256}).ToList();asset.Status="Ready";if(LoseReadyAcknowledgement)throw new IOException("test lost acknowledgement");return Task.CompletedTask;}public Task FailAsync(PublicImageAsset asset,CancellationToken ct){asset.Status="Failed";return Task.CompletedTask;}public Task<PublicImageAsset?> FindReadyAsync(string id,CancellationToken ct)=>Task.FromResult(Assets.TryGetValue(id,out var asset)&&asset.Status=="Ready"?asset:null);}
}
